use backbone_orm::company_scope;

use crate::domain::entity::MaintenanceVisitPart;

/// Table name for MaintenanceVisitPart entities
pub const TABLE_NAME: &str = "maintenance.maintenance_visit_parts";

/// Repository for MaintenanceVisitPart entities.
