/// A part line as the completion path reads it — quantity only; it is valued on completion.
pub struct VisitPartRow {
    pub id: Uuid,
    pub item_id: Uuid,
    pub quantity: Decimal,
}

/// Hand-written MaintenanceVisitPart SQL. Lives here (not in the write service) per the module's
/// 4-layer rule: services orchestrate and own the unit of work, repositories hold the SQL.
impl MaintenanceVisitPartRepository {
    /// Add a part line to a visit (quantity only; `unit_cost`/`amount` are valued on completion).
    ///
    /// ID-only: no company argument. `execute_scoped` means it rides a connection carrying the caller's
    /// `app.company_id`; the visit-status check the caller makes first is what fences the line to a
    /// visit it may see.
    pub async fn insert_part(
        &self,
        pool: &PgPool,
        id: Uuid,
        visit_id: Uuid,
        item_id: Uuid,
        quantity: Decimal,
    ) -> Result<(), sqlx::Error> {
        company_scope::execute_scoped(
            pool,
            sqlx::query(
                r#"INSERT INTO maintenance.maintenance_visit_parts (id, visit_id, item_id, quantity, unit_cost, amount)
                   VALUES ($1,$2,$3,$4,0,0)"#,
            )
            .bind(id).bind(visit_id).bind(item_id).bind(quantity),
        )
        .await?;
        Ok(())
    }

    /// The visit's frozen part set. Caller supplies the company scope
    /// (`with_company_scope(Some(company_id))`).
    pub async fn list_for_visit(
        &self,
        pool: &PgPool,
        visit_id: Uuid,
    ) -> Result<Vec<VisitPartRow>, sqlx::Error> {
        let rows = company_scope::fetch_all_rows_scoped(
            pool,
            sqlx::query(
                "SELECT id, item_id, quantity FROM maintenance.maintenance_visit_parts WHERE visit_id=$1",
            )
            .bind(visit_id),
        )
        .await?;
        Ok(rows
            .iter()
            .map(|r| VisitPartRow {
                id: r.get("id"), item_id: r.get("item_id"), quantity: r.get("quantity"),
            })
            .collect())
    }

    /// Write back the valuation inventory returned for one line (moving-average rate and extended
    /// value). Caller supplies the company scope, as above; both values are expected already
    /// money-rounded.
    pub async fn set_valuation(
        &self,
        pool: &PgPool,
        visit_id: Uuid,
        item_id: Uuid,
        unit_cost: Decimal,
        amount: Decimal,
    ) -> Result<(), sqlx::Error> {
        company_scope::execute_scoped(
            pool,
            sqlx::query(
                r#"UPDATE maintenance.maintenance_visit_parts SET unit_cost=$3, amount=$4
                   WHERE visit_id=$1 AND item_id=$2"#,
            )
            .bind(visit_id).bind(item_id).bind(unit_cost).bind(amount),
        )
        .await?;
        Ok(())
    }
}

